    pub async fn update(
        &self,
        actor_user_id: i64,
        is_superadmin: bool,
        source_calendar_id: i64,
        event_id: i64,
        change: EventChange,
    ) -> Result<EventProjection, EventServiceError> {
        let EventChange {
            expected_version,
            target_calendar_id,
            event,
        } = change;
        validate_mutation(&event)?;
        let now = (self.clock)();
        let timing = StoredTiming::from(&event.timing);
        let mut transaction = self.pool.begin_with("BEGIN IMMEDIATE").await?;
        authorize_in_transaction(
            &mut transaction,
            actor_user_id,
            is_superadmin,
            source_calendar_id,
            CalendarAction::EditAnyEvent,
        )
        .await?;
        if target_calendar_id != source_calendar_id {
            authorize_in_transaction(
                &mut transaction,
                actor_user_id,
                is_superadmin,
                target_calendar_id,
                CalendarAction::EditAnyEvent,
            )
            .await?;
        }
        ensure_not_imported(&mut transaction, event_id).await?;
        let is_recurring: bool = sqlx::query_scalar(
            "SELECT EXISTS(
                SELECT 1 FROM events
                WHERE calendar_id = ? AND id = ? AND recurrence_rule IS NOT NULL
             )",
        )
        .bind(source_calendar_id)
        .bind(event_id)
        .fetch_one(&mut *transaction)
        .await?;
        let result = sqlx::query(
            "UPDATE events
             SET calendar_id = ?, title = ?, description = ?, location = ?, status = ?,
                 event_kind = ?, timed_start_utc = ?, timed_end_utc = ?,
                 event_timezone = ?, all_day_start_date = ?, all_day_end_date = ?,
                 last_edited_by_user_id = ?, version = version + 1, updated_at = ?
             WHERE calendar_id = ? AND id = ? AND version = ?",
        )
        .bind(target_calendar_id)
        .bind(&event.title)
        .bind(&event.description)
        .bind(&event.location)
        .bind(event.status.as_str())
        .bind(timing.kind)
        .bind(timing.timed_start_utc)
        .bind(timing.timed_end_utc)
        .bind(timing.timezone)
        .bind(timing.all_day_start_date)
        .bind(timing.all_day_end_date)
        .bind(actor_user_id)
        .bind(now)
        .bind(source_calendar_id)
        .bind(event_id)
        .bind(expected_version)
        .execute(&mut *transaction)
        .await?;
        if result.rows_affected() != 1 {
            let current_version: Option<i64> =
                sqlx::query_scalar("SELECT version FROM events WHERE calendar_id = ? AND id = ?")
                    .bind(source_calendar_id)
                    .bind(event_id)
                    .fetch_optional(&mut *transaction)
                    .await?;
            transaction.rollback().await?;
            return match current_version {
                Some(current_version) => Err(EventServiceError::Conflict { current_version }),
                None => Err(EventServiceError::NotFound),
            };
        }
        if is_recurring {
            sqlx::query("DELETE FROM event_recurrence_exceptions WHERE series_id = ?")
                .bind(event_id)
                .execute(&mut *transaction)
                .await?;
        }
        insert_event_audit(
            &mut transaction,
            actor_user_id,
            "event.update",
            event_id,
            now,
        )
        .await?;
        if target_calendar_id != source_calendar_id {
            let resource_name: Option<String> = sqlx::query_scalar(
                "SELECT resource_name FROM caldav_event_resources
                  WHERE calendar_id = ? AND event_id = ? AND deleted_at IS NULL",
            )
            .bind(source_calendar_id)
            .bind(event_id)
            .fetch_optional(&mut *transaction)
            .await?;
            record_caldav_change(
                &mut transaction,
                source_calendar_id,
                event_id,
                "deleted",
                now,
                resource_name.as_deref(),
            )
            .await?;
            record_caldav_change(
                &mut transaction,
                target_calendar_id,
                event_id,
                "created",
                now,
                None,
            )
            .await?;
            sqlx::query(
                "UPDATE caldav_event_resources
                     SET calendar_id = ?, updated_at = ?
                   WHERE event_id = ? AND deleted_at IS NULL",
            )
            .bind(target_calendar_id)
            .bind(now)
            .bind(event_id)
            .execute(&mut *transaction)
            .await?;
        } else {
            record_caldav_change(
                &mut transaction,
                target_calendar_id,
                event_id,
                "updated",
                now,
                None,
            )
            .await?;
        }
        transaction.commit().await?;
        self.notification_replanner.send(event_id).await;
        self.get(actor_user_id, is_superadmin, target_calendar_id, event_id)
            .await
    }

    pub async fn delete(
        &self,
        actor_user_id: i64,
        is_superadmin: bool,
        calendar_id: i64,
        event_id: i64,
    ) -> Result<(), EventServiceError> {
        let now = (self.clock)();
        let mut transaction = self.pool.begin_with("BEGIN IMMEDIATE").await?;
        authorize_in_transaction(
            &mut transaction,
            actor_user_id,
            is_superadmin,
            calendar_id,
            CalendarAction::EditAnyEvent,
        )
        .await?;
        ensure_not_imported(&mut transaction, event_id).await?;
        sqlx::query(
            "UPDATE notification_jobs SET state = 'cancelled', updated_at = ?
             WHERE event_id = ? AND state = 'pending'",
        )
        .bind(now)
        .bind(event_id)
        .execute(&mut *transaction)
        .await?;
        // Capture the DAV resource name from the live mapping before the
        // tombstone clears the event reference. The change log carries it so
        // sync-collection (T11) can emit the correct href for the deletion.
        let resource_name: Option<String> = sqlx::query_scalar(
            "SELECT resource_name FROM caldav_event_resources
              WHERE calendar_id = ? AND event_id = ? AND deleted_at IS NULL",
        )
        .bind(calendar_id)
        .bind(event_id)
        .fetch_optional(&mut *transaction)
        .await?;
        // Tombstone the live DAV mapping (if any) before removing the event so
        // the mapping's foreign key stays satisfied and the deletion is durable
        // for other clients. Then record the deletion in the change log. Both
        // share this transaction, so a rolled-back delete leaves neither.
        tombstone_caldav_mapping(&mut transaction, calendar_id, event_id, now).await?;
        record_caldav_change(
            &mut transaction,
            calendar_id,
            event_id,
            "deleted",
            now,
            resource_name.as_deref(),
        )
        .await?;
        let deleted = sqlx::query("DELETE FROM events WHERE calendar_id = ? AND id = ?")
            .bind(calendar_id)
            .bind(event_id)
            .execute(&mut *transaction)
            .await?;
        if deleted.rows_affected() != 1 {
            transaction.rollback().await?;
            return Err(EventServiceError::NotFound);
        }
        insert_event_audit(
            &mut transaction,
            actor_user_id,
            "event.delete",
            event_id,
            now,
        )
        .await?;
        transaction.commit().await?;
        self.notification_replanner.send(event_id).await;
        Ok(())
    }

    async fn read_access(
        &self,
        actor_user_id: i64,
        is_superadmin: bool,
        calendar_id: i64,
    ) -> Result<EventAccess, EventServiceError> {
        let role: Option<String> = sqlx::query_scalar(
            "SELECT role FROM calendar_acl WHERE calendar_id = ? AND user_id = ?",
        )
        .bind(calendar_id)
        .bind(actor_user_id)
        .fetch_optional(&self.pool)
        .await?;
        let role = role
            .as_deref()
            .and_then(|role| CalendarRole::from_str(role).ok())
            .ok_or(EventServiceError::NotFound)?;
        let platform_role = if is_superadmin {
            PlatformRole::Superadmin
        } else {
            PlatformRole::User
        };
        if authorize_calendar_action(
            UserStatus::Active,
            Some(platform_role),
            Some(role),
            CalendarAction::ReadDetails,
        ) == AuthorizationDecision::Allow
        {
            Ok(EventAccess::Details)
        } else if authorize_calendar_action(
            UserStatus::Active,
            Some(platform_role),
            Some(role),
            CalendarAction::ReadFreeBusy,
        ) == AuthorizationDecision::Allow
        {
            Ok(EventAccess::FreeBusy)
        } else {
            Err(EventServiceError::NotFound)
        }
    }
}

