                       DTSTAMP:20260101T000000Z\r\n\
                       DTSTART:20260115T000000Z\r\n\
                       DTEND:20260115T010000Z\r\n\
                       RRULE:FREQ=DAILY;COUNT=5\r\n\
                       SUMMARY:Original\r\n\
                       END:VEVENT\r\n\
                       END:VCALENDAR\r\n";
    let (create_status, _, _) = put_request(
